<template><view class="edition-page" :class="[AppStyle,{'is-night':isNight}]"><view class="edition-nav"><text @tap="back" class="cuIcon-back"/><text class="nav-title">{{journal.name||'刊物'}}</text><text @tap="openSubmit" class="cuIcon-edit"/></view><view class="edition-hero" :style="heroStyle"><image v-if="journal.bannerUrl||journal.coverUrl" :src="journal.bannerUrl||journal.coverUrl" mode="aspectFill"/><view class="shade"/><view class="hero-copy"><text class="kicker">CAMPUS EDITION</text><text class="hero-title">{{journal.name||'校园刊物'}}</text><text class="hero-desc">{{journal.description||'记录校园生活，也记录正在发生的思想。'}}</text></view></view><view class="edition-meta"><text>{{articles.length}} 篇文章</text><text v-for="tag in journalTags" :key="tag">{{tag}}</text><text @tap="openSubmit" class="submit">我要投稿 ·</text></view><view class="tools"><text>本刊文章</text><view><text v-for="item in sortOptions" :key="item.value" :class="{active:sort===item.value}" @tap="changeSort(item.value)">{{item.label}}</text></view></view><view class="article-list"><view v-for="item in articles" :key="item.id" class="article" @tap="openArticle(item)"><view class="copy"><text class="date">{{displayDate(item.publishedAt||item.created)}} · {{item.views||0}} 阅读</text><text class="title">{{item.title}}</text><text class="summary">{{item.summary||excerpt(item.bodyMarkdown)}}</text><text class="author">{{item.authorName||'见字作者'}} · <text class="cuIcon-right"/></text></view><image v-if="item.coverUrl" :src="item.coverUrl" mode="aspectFill"/></view><view v-if="loading" class="state">正在翻开下一页</view><view v-else-if="!articles.length" class="state">本刊还没有公开文章 · <text @tap="openSubmit">向本刊投稿</text></view></view></view></template>
<script>
import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js';import { applyCampusThemeShell,getCampusThemeMode } from '@/utils/campusTheme.js'
export default {data(){return {AppStyle:this.$store.state.AppStyle,isNight:false,id:0,journal:{},articles:[],sort:'latest',loading:true,sortOptions:[{label:'最新',value:'latest'},{label:'热门',value:'hot'},{label:'推荐',value:'recommend'}]}},computed:{journalTags(){return String(this.journal.tags||'').split(/[,，]/).map(v=>v.trim()).filter(Boolean)},heroStyle(){return {background:this.journal.bannerUrl?'#29483f':'linear-gradient(135deg,#1d4039,#b07852)'}}},onLoad(q){this.id=Number(q.id||0);this.loadJournal();this.loadArticles()},onShow(){this.isNight=applyCampusThemeShell(getCampusThemeMode(),Date.now());this.loadJournal();this.loadArticles()},methods:{back(){uni.navigateBack({delta:1})},token(){try{return JSON.parse(localStorage.getItem('userinfo')||'{}').token||''}catch(e){return ''}},loadJournal(){if(!this.id)return;this.$Net.request({url:this.$API.journalInfo(),data:{id:this.id,token:this.token(),_ts:Date.now()},method:'get',dataType:'json',success:r=>{if(r.data&&r.data.code===1)this.journal=r.data.data||{}}})},loadArticles(){this.loading=true;this.$Net.request({url:this.$API.journalArticleList(),data:{journalId:this.id,page:1,limit:50,sort:this.sort,token:this.token(),_ts:Date.now()},method:'get',dataType:'json',success:r=>{const rows=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[];this.articles=rows.filter(item=>item&&item.status==='published');this.loading=false},fail:()=>{this.articles=[];this.loading=false}})},changeSort(v){if(this.sort!==v){this.sort=v;this.loadArticles()}},openSubmit(){uni.navigateTo({url:'/pages/journal/post?journalId='+this.id+'&journalName='+encodeURIComponent(this.journal.name||'')})},openArticle(a){uni.navigateTo({url:'/pages/journal/article?id='+a.id})},excerpt(v){return String(v||'').replace(/[#>*_`\[\]]/g,'').replace(/!\[[^\]]*\]\([^)]*\)/g,'').replace(/\s+/g,' ').trim().slice(0,110)},displayDate(v){let d=new Date(Number(v)>10000000000?Number(v):Number(v)*1000);return isNaN(d.getTime())?'':d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0')}}}
</script>
<style scoped>.edition-page{min-height:100vh;background:#f4f1eb;color:#1b2c27}.edition-nav{position:sticky;top:0;z-index:5;display:flex;justify-content:space-between;align-items:center;padding:calc(22px + env(safe-area-inset-top)) 24px 16px;background:rgba(244,241,235,.92);backdrop-filter:blur(18px);font-size:20px;color:#34534b}.nav-title{font:21px Georgia,serif}.edition-hero{position:relative;min-height:330px;overflow:hidden;background-size:cover}.edition-hero image{position:absolute;width:100%;height:100%;opacity:.68}.shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,20,17,.08),rgba(7,20,17,.85))}.hero-copy{position:absolute;left:24px;right:24px;bottom:30px;color:#fff}.kicker,.date{font-size:10px;letter-spacing:2px;opacity:.72}.hero-title{display:block;margin-top:12px;font:42px Georgia,serif}.hero-desc{display:block;margin-top:10px;max-width:540px;line-height:1.6;opacity:.84}.edition-meta,.tools{display:flex;justify-content:space-between;gap:14px;align-items:center;padding:18px 24px;border-bottom:1px solid rgba(44,72,64,.13);font-size:12px;color:#71817a}.edition-meta .submit{margin-left:auto;color:#a0643f}.tools{padding-top:26px;font:21px Georgia,serif;color:#294a40}.tools view{display:flex;gap:18px;font:13px sans-serif;color:#8a9891}.tools view .active{color:#a0643f;border-bottom:2px solid #a0643f;padding-bottom:7px}.article{display:flex;gap:18px;padding:24px;border-bottom:1px solid rgba(44,72,64,.13)}.copy{flex:1;min-width:0}.title{display:block;margin:10px 0 8px;font:28px/1.2 Georgia,serif;color:#203c35}.summary{display:block;color:#71817a;line-height:1.6}.author{display:block;margin-top:16px;color:#55776b;font-size:12px}.article image{flex:0 0 120px;width:120px;height:130px;border-radius:6px}.state{text-align:center;padding:70px 24px;color:#8a9891}.state text{color:#567f70}.is-night{background:#1f2926;color:#e6eee9}.is-night .edition-nav{background:rgba(31,41,38,.94);color:#e6eee9}.is-night .title,.is-night .tools{color:#e6eee9}@media(max-width:480px){.hero-title{font-size:38px}.article image{flex-basis:92px;width:92px;height:108px}.title{font-size:23px}}</style>
